contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller will be this contract when interacting with c
    function run() public payable {
        // no precondition
        // 1) deposit some Ether into c from this contract to set up a nonzero balance
        // ensure this contract has enough balance to send; msg.value is not used for calls to c
        require(address(this).balance >= 0);

        // choose an amount to deposit: use a nonzero small constant via parameter-like behavior by using msg.gas (allowed),
        // but we must not rely on environment; instead deposit 1 wei if possible by checking balance
        uint256 depositAmount = 1;
        if (address(this).balance < depositAmount) {
            // cannot proceed to meaningful test, but must reach assert; set depositAmount = 0
            depositAmount = 0;
        }

        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // read recorded before-balance for this contract (auto getter exists: balances is private so no getter; cannot access)
        // balances mapping in C is internal/private so no getter — we must observe by effects: address(c).balance and refund transfer outcome
        // To capture the amount that will be refunded, we invoke refund and measure balances around it.

        // record contract balances before refund
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        bool reverted;
        // call refund and catch revert
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        // General rule: if refund did not revert, then after refund this contract's recorded balance must be zero (observable by no further Ether retained for it)
        // Since we cannot read internal balances, we express observable consequence: if refund succeeded, caller's received Ether increased by exactly the amount that the contract's balance decreased (i.e., funds were transferred out), and contract balance did not increase.
        // Also refund sets caller's recorded balance to zero; to observe that a subsequent withdraw of any positive amount must revert. We'll check that calling withdraw(1) reverts after successful refund.

        bool withdrawReverted;
        try c.withdraw(1) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Assert general rule combining observations:
        // If refund succeeded then: (1) contract balance did not increase (cBalAfter <= cBalBefore),
        // (2) this contract's balance increased by exactly the decrease of the contract (selfBalAfter >= selfBalBefore),
        // and (3) any attempt to withdraw a positive amount now reverts (withdrawReverted == true).
        assert( (!reverted) ? (cBalAfter <= cBalBefore && selfBalAfter >= selfBalBefore && (cBalBefore - cBalAfter) <= selfBalAfter - selfBalBefore && withdrawReverted) : true );
    }

    // receive to accept refunds
    receive() external payable {}
}

