contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256 amount) public payable {
        // If we intend to deposit Ether we must have it available here
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        // read before-values (publicly observable)
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // attempt deposit and record whether it reverted
        bool depositReverted;
        try c.deposit{value: amount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read after-values
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // General rule: if deposit did not revert then recorded balance increased by exactly amount
        // and contract balance increased by at least amount
        assert(depositReverted || (afterRecorded == beforeRecorded + amount && afterContractBal >= beforeContractBal + amount));
    }

    // accept Ether sent from C
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot observe c.balances (it's not public), so assert a rule about observable Ether balances only.
    // If deposit succeeds (doesn't revert), the contract C's on-chain balance must increase by exactly the sent amount,
    // and this test contract's balance must decrease by at least that amount.
    function run(uint256 amount) public payable {
        // If we plan to send Ether to c, ensure this contract has it available
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        uint256 beforeC = address(c).balance;
        uint256 beforeSelf = address(this).balance;

        bool depositReverted;
        try c.deposit{value: amount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterSelf = address(this).balance;

        // General rule: either deposit reverted, or C's balance increased by exactly amount
        // and this contract's balance did not increase (i.e., decreased or same) by at least amount.
        // We use afterSelf <= beforeSelf to express that this contract did not gain Ether.
        assert(depositReverted || (afterC == beforeC + amount && afterSelf + amount <= beforeSelf));
    }

    // accept Ether sent from C
    receive() external payable {}
}

