contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to deposit an amount and then check observable effects.
    // Because balances mapping is not public, we observe the depositor's recorded balance indirectly:
    // after deposit, trying to withdraw up to the deposited amount should succeed (i.e., not revert)
    // unless withdraw would exceed the recorded balance. We capture reverts with try/catch.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // read before-values
        uint256 beforeContractBalance = address(c).balance;

        // perform deposit on c, sending Ether
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read after-values
        uint256 afterContractBalance = address(c).balance;

        // Now probe whether the contract considers this test contract to have at least `depositAmount` balance
        // by attempting to withdraw exactly depositAmount. If withdraw reverts then recorded balance < depositAmount.
        bool withdrawReverted;
        try c.withdraw(depositAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // General rule asserted:
        // If deposit did not revert then (1) contract balance increased by exactly depositAmount, and
        // (2) withdrawing depositAmount should NOT revert (i.e., recorded balance for this caller is >= depositAmount).
        assert(depositReverted || (afterContractBalance == beforeContractBalance + depositAmount && withdrawReverted == false));
    }

    // allow receiving ETH when c.transfer sends funds back to this contract during withdraw/refund
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some amount (as this contract) then call refund and check observable effects.
    // Use try/catch to detect whether refund reverted.
    function run(uint256 depositAmount) public payable {
        // ensure this test contract has enough ETH to send to c
        require(address(this).balance >= depositAmount);

        // record contract-wide balance of c before deposit
        uint256 beforeCBalance = address(c).balance;

        // try to deposit funds to c from this contract
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // record contract-wide balance of c after deposit (whether deposit reverted or not)
        uint256 afterDepositCBalance = address(c).balance;

        // Now attempt refund() (this will transfer this contract's recorded balance in c back to this contract)
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // record c balance after refund attempt
        uint256 afterRefundCBalance = address(c).balance;

        // If refund did not revert, then the contract's balance must have decreased by exactly the amount
        // that this contract gained from the refund. We cannot read the internal mapping, but we can observe
        // that the net decrease in c's balance equals the net increase in this contract's balance.
        // Compute this contract's observable balance change: current balance minus what it was at start of run.
        uint256 ourBalanceAfter = address(this).balance;

        // To get our starting balance at function entry we use: ourBalanceAfter - (gain from refund) + (amount we sent in deposit if it succeeded)
        // Rearranged check: if refund succeeded, then (beforeCBalance + (depositSucceeded ? depositAmount : 0)) - afterRefundCBalance == ourBalanceAfter - (address(this).balance - 0);
        // Simpler: If refund succeeded then the decrease in c balance from just before refund to after refund equals the increase in this contract's balance during the refund call.

        // balance of c just before refund was afterDepositCBalance
        uint256 decreaseInC = afterDepositCBalance - afterRefundCBalance;

        // The increase observed for this contract due only to the refund equals our current balance minus what it would have been had we not received the refund.
        // But we can express an invariant without needing the exact before-run our balance: when refund succeeds, c's balance decreases by exactly the amount transferred to this contract (which equals our observed increase between after deposit and now plus any transferouts we might have sent, but we did not send during run). Since this test makes no outgoing transfers after deposit until after refund, the increase in this contract's balance since after deposit equals the refund amount.

        // Compute our balance right after deposit: assume no other changes, it's ourBalanceAfter minus decrease due to sending deposit plus increase due to refund.
        // However to avoid complex algebra, assert a relation purely on observable c balances and whether refund reverted:

        // General rule: if refund did NOT revert then (1) afterRefundCBalance == afterDepositCBalance - decreaseInC (tautology) and (2) decreaseInC > 0 implies this contract's balance increased by exactly decreaseInC compared to just after deposit.
        // We implement (2) by checking that if refund did not revert then afterDepositCBalance >= afterRefundCBalance and the net increase in this contract's balance since the deposit equals that decrease.

        // To get our balance just after deposit, reconstruct it: start with current balance, subtract amount we received from refund (unknown), add depositAmount if deposit succeeded.
        // Easier approach: call withdraw of a large amount to determine if recorded balance is zero after refund: if refund succeeded then a subsequent withdraw of any positive amount should revert (no balance). We'll use withdraw(1) as a probe.

        bool withdrawRevertedAfterRefund;
        try c.withdraw(1) {
            withdrawRevertedAfterRefund = false;
        } catch {
            withdrawRevertedAfterRefund = true;
        }

        // Final assertion: if refund succeeded then (1) c's balance did not increase due to the refund: afterRefundCBalance <= afterDepositCBalance, and (2) withdraw(1) should revert (since refund zeroes the caller's recorded balance).
        assert(refundReverted || (afterRefundCBalance <= afterDepositCBalance && withdrawRevertedAfterRefund));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an arbitrary amount to deposit into c, then call migrateTo as the creator
    // (this contract deployed c, so it is the creator). We assert that if migrateTo did not revert,
    // then the observable balance of c becomes zero.
    function run(uint256 depositAmount, address payable to) public payable {
        // ensure this test contract has enough ETH to send to c for the deposit
        require(address(this).balance >= depositAmount);

        // Make a deposit into c from this contract. If deposit reverts, we record that.
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Record c's balance before migrate
        uint256 beforeMigrate = address(c).balance;

        // Attempt migrateTo and record whether it reverted
        bool migrateReverted;
        try c.migrateTo(to) {
            migrateReverted = false;
        } catch {
            migrateReverted = true;
        }

        uint256 afterMigrate = address(c).balance;

        // General rule: if migrateTo did not revert then c's observable balance is zero afterwards.
        // Also ensure that if migrate did not revert then beforeMigrate >= afterMigrate (no creation of funds).
        assert(migrateReverted || (afterMigrate == 0 && beforeMigrate >= afterMigrate));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will not call deposit to avoid triggering C.deposit's internal assert.
    // Instead, we rely on the initial fresh contract having zero balances. The test
    // takes an amount and attempts withdraw from this contract (msg.sender == InvMutTest).
    // We observe whether withdraw reverts and compare address(c).balance before/after.
    function run(uint256 withdrawAmount) public payable {
        // No precondition on withdrawAmount. Ensure this test does not send Ether anywhere.

        // Observe contract balance before the call.
        uint256 before = address(c).balance;

        // Try to call withdraw and record if it reverted.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint256 after = address(c).balance;

        // General rule:
        // If withdraw did not revert, then before >= after (contract balance does not increase)
        // and the decrease (before - after) is <= withdrawAmount (it transfers at most the requested amount).
        // If withdraw reverted, nothing is required. This avoids subtraction underflow by guarding with !withdrewReverted.
        assert(withdrewReverted || (before >= after && (before - after) <= withdrawAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters to drive deposit and withdraw
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        // Ensure this test contract has enough ETH to forward depositAmt
        require(address(this).balance >= depositAmt, "insufficient test balance");
        // 1) Deposit depositAmt into c from this contract
        c.deposit{value: depositAmt}();

        // Record contract balance before withdraw attempt
        uint256 beforeContractBal = address(c).balance;

        // Attempt withdraw and capture whether it reverted
        bool withdrew;
        // withdraw modifies c state; must be a top-level statement in the function
        try c.withdraw(withdrawAmt) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        uint256 afterContractBal = address(c).balance;

        // If withdraw succeeded, contract balance must have decreased by withdrawAmt (exactly)
        // If withdraw reverted, contract balance must be unchanged
        assert(
            (withdrew && beforeContractBal == afterContractBal + withdrawAmt) ||
            (!withdrew && beforeContractBal == afterContractBal)
        );
    }

    // allow contract to receive ETH so it can forward deposits in tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable target;

    constructor(C _c) {
        c = _c;
        // pick some target address different from this contract
        target = payable(address(0x100));
    }

    // single public function driving migrateTo; payable so this test can fund c beforehand
    function run(uint256 seedDeposit) public payable {
        // ensure this contract has enough ETH to deposit
        require(address(this).balance >= seedDeposit, "insufficient test balance");

        // Seed the target contract by depositing some ETH into c from this contract
        // (deposit can revert if overflow; avoid overflow by bounding seedDeposit)
        uint256 safeDeposit = seedDeposit;
        if (safeDeposit > 1 ether) {
            safeDeposit = 1 ether;
        }
        c.deposit{value: safeDeposit}();

        // Record contract balance before migrate
        uint256 before = address(c).balance;

        // Try calling migrateTo and capture whether it reverted
        bool migrated;
        try c.migrateTo(target) {
            migrated = true;
        } catch {
            migrated = false;
        }

        uint256 after = address(c).balance;

        // If migrateTo was called by the creator it should forward the full balance and leave zero.
        // In this environment the InvMutTest contract deployed c, so msg.sender for calls from here is this contract.
        // The general rule: if migrateTo did not revert then after == 0 and before == amount forwarded (i.e., before >= after and after == 0)
        assert((migrated && after == 0) || (!migrated && after == before));
    }

    // receive to accept ETH forwarded by c during migration
    receive() external payable {}
}

