contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We model a sequence: optionally deposit some ETH from this contract into c,
    // then call either withdraw or refund, and assert an invariant relating
    // address(c).balance and the visible balances mapping for this contract.
    // Parameters:
    // - depositAmount: amount to send to c.deposit()
    // - doRefund: if true call c.refund(), else call c.withdraw(withdrawAmount)
    // - withdrawAmount: amount to attempt to withdraw when doRefund == false
    function run(uint256 depositAmount, bool doRefund, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Read before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeRecorded = c.balances(address(this));

        // Perform deposit if requested
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // After deposit, read intermediate values
        uint256 midContractBalance = address(c).balance;
        uint256 midRecorded = c.balances(address(this));

        // Decide and perform withdraw/refund, capturing whether it reverted
        bool reverted = false;
        if (doRefund) {
            try c.refund() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values
        uint256 afterContractBalance = address(c).balance;
        uint256 afterRecorded = c.balances(address(this));

        // General rule asserted:
        // 1) Any successful withdraw/refund cannot increase the contract's balance: afterContractBalance <= midContractBalance when not reverted.
        // 2) The sum (contract balance + recorded balance for this address) after the operation equals the same sum before the operation, unless the call reverted (in which case state is unchanged and equality still holds).
        // We express both as a single conjunction.
        assert((reverted || afterContractBalance <= midContractBalance) && (afterContractBalance + afterRecorded == midContractBalance + midRecorded));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read the internal balances mapping directly. To observe the caller's recorded balance
    // we infer it by performing a refundable sequence: call refund() to learn the recorded balance
    // (it transfers recorded balance and sets it to 0). Then we can optionally redeposit that exact
    // amount back to restore the recorded balance to its previous value and reason about conservation.
    // Parameters:
    // - initialDeposit: amount to deposit first (to increase both recorded and contract balances)
    // - doWithdraw: if true attempt withdraw(withdrawAmount), else attempt refund()
    // - withdrawAmount: amount to attempt to withdraw when doWithdraw == true
    // The test observes contract balance and uses refund to extract the caller-recorded balance.
    function run(uint256 initialDeposit, bool doWithdraw, uint256 withdrawAmount) public payable {
        require(address(this).balance >= initialDeposit);

        // Record contract balance before any actions
        uint256 beforeContract = address(c).balance;

        // Optionally deposit some Ether to c from this contract
        if (initialDeposit > 0) {
            c.deposit{value: initialDeposit}();
        }

        // After deposit
        uint256 midContract = address(c).balance;

        // Now call refund() to learn this contract's recorded balance in c.
        // refund() will transfer the recorded balance to this contract and set it to 0.
        bool refundReverted = false;
        uint256 refundedAmount = 0;
        // capture our balance before refund to compute refundedAmount
        uint256 beforeSelf = address(this).balance;
        try c.refund() {
            refundReverted = false;
            refundedAmount = address(this).balance - beforeSelf;
        } catch {
            refundReverted = true;
            refundedAmount = 0;
        }

        // After refund attempt, contract balance decreased by refundedAmount if success
        uint256 afterRefundContract = address(c).balance;

        // If refund succeeded, we restored caller's recorded balance to 0 and received refundedAmount.
        // To allow further withdraw calls that expect a nonzero recorded balance, we can redeposit refundedAmount
        // to restore the previous recorded balance observed by refund. This keeps overall sums consistent.
        if (!refundReverted && refundedAmount > 0) {
            // ensure we have the refunded funds available to redeposit
            require(address(this).balance >= refundedAmount);
            c.deposit{value: refundedAmount}();
        }

        // Now attempt the targeted operation (withdraw or refund) and record whether it reverted
        bool opReverted = false;
        uint256 beforeOpContract = address(c).balance;
        uint256 beforeOpSelf = address(this).balance;
        if (doWithdraw) {
            try c.withdraw(withdrawAmount) {
                opReverted = false;
            } catch {
                opReverted = true;
            }
        } else {
            try c.refund() {
                opReverted = false;
            } catch {
                opReverted = true;
            }
        }
        uint256 afterOpContract = address(c).balance;
        uint256 afterOpSelf = address(this).balance;

        // We cannot read the internal mapping, but we can state a general conservation rule using observed quantities:
        // Let Total_before = midContract (contract balance after initial deposit) + refundedAmount (the recorded balance we observed via refund).
        // After the sequence (including possible redeposit and the final operation), for any successful final operation:
        //   - the contract's Ether never increases (afterOpContract <= beforeOpContract)
        //   - the sum (contract balance + caller-observable withdrawable amount) equals Total_before.
        // We express the second part by using that when a refund succeeds, caller receives its recorded balance. Thus,
        // the caller's withdrawable amount just before the final operation equals refundedAmount (if refund succeeded earlier) or is unknown (if refund earlier reverted).

        // To keep the assertion general and provable from public observations, we assert:
        // If the initial refund succeeded (so we observed refundedAmount) then for a non-reverting final operation:
        //   afterOpContract + (afterOpSelf - beforeOpSelf) == beforeOpContract + refundedAmount
        // and the contract's balance did not increase: afterOpContract <= beforeOpContract.

        // Build the asserted relation. Only claim it when the initial refund succeeded (so refundedAmount is known)
        // and the final operation did NOT revert (so state changed accordingly).
        assert((refundReverted) || (opReverted) || ((afterOpContract <= beforeOpContract) && (afterOpContract + (afterOpSelf - beforeOpSelf) == beforeOpContract + refundedAmount)));
    }

    receive() external payable {}
}

