contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // initialDeposit: deposit at start to ensure some balance (may be 0)
    // doWithdraw: whether to perform withdraw(amount) after the refund/deposit sequence
    // withdrawAmount: amount to withdraw if doWithdraw==true
    // redeposit: whether to redeposit the refunded amount when refund succeeds
    function run(uint256 initialDeposit, bool doWithdraw, uint256 withdrawAmount, bool redeposit) public payable {
        require(address(this).balance >= initialDeposit);

        // Optional initial deposit to set up state.
        if (initialDeposit > 0) {
            c.deposit{value: initialDeposit}();
        }

        // Observe contract balance before refund
        uint256 beforeRefundContract = address(c).balance;
        uint256 beforeRefundSelf = address(this).balance;

        // Call refund() and observe whether it reverts and how much Ether this contract receives
        bool refundReverted;
        uint256 afterRefundSelf;
        try c.refund() {
            refundReverted = false;
            afterRefundSelf = address(this).balance;
        } catch {
            refundReverted = true;
            afterRefundSelf = address(this).balance;
        }

        uint256 gainedFromRefund = afterRefundSelf - beforeRefundSelf;

        // If refund succeeded and redeposit requested, redeposit the exact amount gainedFromRefund
        // Ensure we have the Ether available to redeposit
        if (!refundReverted && redeposit && gainedFromRefund > 0) {
            require(address(this).balance >= gainedFromRefund);
            c.deposit{value: gainedFromRefund}();
        }

        // Observe contract balance before the final operation
        uint256 beforeOpContract = address(c).balance;
        uint256 beforeOpSelf = address(this).balance;

        // Perform the final operation: either withdraw(withdrawAmount) or refund()
        bool opReverted;
        if (doWithdraw) {
            try c.withdraw(withdrawAmount) {
                opReverted = false;
            } catch {
                opReverted = true;
            }
        } else {
            try c.refund() {
                opReverted = false;
            } catch {
                opReverted = true;
            }
        }

        uint256 afterOpContract = address(c).balance;
        uint256 afterOpSelf = address(this).balance;

        // General rule asserted:
        // If the initial refund succeeded and we redeposited the exact refunded amount, then after that redeposit
        // the contract's balance must equal the contract's balance before the initial refund.
        // Additionally, if the final operation did not revert, then it cannot increase the contract's balance
        // (i.e., afterOpContract <= beforeOpContract), and the total of (afterOpContract + (afterOpSelf - beforeOpSelf))
        // equals (beforeOpContract + (redeposit ? 0 : gainedFromRefund)). The term (redeposit ? 0 : gainedFromRefund)
        // accounts for whether the refunded amount was returned to the contract before the final op.
        assert(
            (
                refundReverted || !redeposit || (address(c).balance == beforeRefundContract)
            )
            && (
                opReverted || (afterOpContract <= beforeOpContract && (afterOpContract + (afterOpSelf - beforeOpSelf) == beforeOpContract + (redeposit ? 0 : gainedFromRefund)))
            )
        );
    }

    receive() external payable {}
}

