contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We observe balances for this contract's address via the auto-generated getter balances(address)
    // The test drives deposit and then either withdraw or refund, and asserts that any change in
    // address(c).balance matches the change in the recorded mapping balance for this caller.

    function run(uint256 depositAmount, bool doRefund, uint256 withdrawAmount) public payable {
        // Ensure we have enough Ether to send when depositing
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Read before-values
        uint256 beforeMapping = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // Make a deposit if requested amount > 0
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Read mid-values
        uint256 midMapping = c.balances(address(this));
        uint256 midContractBal = address(c).balance;

        // Either refund or withdraw (withdraw amount only valid if <= mapping; but we try and record revert)
        bool withdrewReverted;
        if (doRefund) {
            try c.refund() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            // attempt withdraw; record if reverted
            try c.withdraw(withdrawAmount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        // Read after-values
        uint256 afterMapping = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // The general invariant we assert:
        // Any increase in the contract's Ether balance between before and mid was exactly reflected
        // by the increase in the caller's recorded mapping balance (deposit effect).
        // And any decrease in the contract balance from mid to after that succeeded (i.e., call did not revert)
        // is exactly reflected by a decrease in the caller's recorded mapping balance.
        // We express this as two equalities guarded by the revert flag where appropriate.

        // Formulas:
        // (midContractBal - beforeContractBal) == (midMapping - beforeMapping)
        // if the withdraw/refund call did not revert then (midContractBal - afterContractBal) == (midMapping - afterMapping)

        assert(
            // deposit side: equal change (handles zero deposit as equality of zeros)
            (midContractBal >= beforeContractBal && midMapping >= beforeMapping && (midContractBal - beforeContractBal) == (midMapping - beforeMapping))
            // and on successful outgoing transfer, equal decrease
            && (withdrewReverted || (midContractBal >= afterContractBal && midMapping >= afterMapping && (midContractBal - afterContractBal) == (midMapping - afterMapping)))
        );
    }

    // Allow receiving Ether from c.transfer calls
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We cannot read C's internal balances mapping (it's not public), so we assert relations only over
    // observable contract balance changes and whether calls revert. The test deposits, then attempts
    // either withdraw or refund, and checks that the contract's Ether balance changes exactly match
    // the Ether amounts sent into or out of C when the calls succeed.
    // Note: msg.sender for calls to C is this contract (InvMutTest), and address(this).balance is used
    // to ensure we have funds to deposit.

    function run(uint256 depositAmount, bool doRefund, uint256 withdrawAmount) public payable {
        // ensure this test contract has enough Ether to perform the deposit
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Read contract balance before any action
        uint256 beforeContractBal = address(c).balance;

        // If depositAmount>0, perform deposit and it should increase c's balance by exactly depositAmount
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        uint256 midContractBal = address(c).balance;

        // The observed increase due to deposit (may be zero if depositAmount==0)
        uint256 observedIncrease = midContractBal >= beforeContractBal ? midContractBal - beforeContractBal : 0;

        // Now attempt an outgoing operation: either refund() or withdraw(withdrawAmount)
        bool didRevert;
        if (doRefund) {
            try c.refund() {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        uint256 afterContractBal = address(c).balance;

        // Determine observed decrease if call succeeded
        uint256 observedDecrease = midContractBal >= afterContractBal ? midContractBal - afterContractBal : 0;

        // General rule asserted:
        // 1) The contract balance increase from before to mid equals the depositAmount provided.
        //    (deposit either increases contract balance exactly by depositAmount or depositAmount==0)
        // 2) If the outgoing call did NOT revert, then the contract balance decreased by exactly the amount
        //    that was transferred out. For refund(), the decrease equals the amount that was in c for this caller
        //    (we cannot observe that directly), but we can assert that a successful withdraw decreases contract
        //    balance exactly by withdrawAmount, and a successful refund decreases contract balance by some non-negative amount.
        // To make a single general assertion over observable values only, we assert:
        // - observedIncrease == depositAmount
        // - if withdraw/refund did not revert then observedDecrease > 0 implies that the contract balance decreased
        //   by an amount consistent with the attempted outgoing operation: for withdraw, exactly withdrawAmount; for refund, some non-negative amount.

        // We encode this as a single assert combining both cases:
        if (!doRefund) {
            // For withdraw path: if the withdraw call did not revert, the contract balance must have decreased by exactly withdrawAmount.
            // If it reverted, no requirement on decrease (it should remain same, but revert may still have left balance unchanged).
            assert(
                // deposit correctness
                observedIncrease == depositAmount
                // and either withdraw reverted or exact decrease equals withdrawAmount
                && (didRevert || observedDecrease == withdrawAmount)
            );
        } else {
            // For refund path: refund should, if it did not revert, reduce contract balance by some non-negative amount.
            // We assert deposit correctness and that if refund succeeded then contract balance did not increase (i.e., mid >= after)
            // and the observedDecrease is <= midContractBal (always true) and >= 0 (trivially true). We express a meaningful condition:
            // if refund succeeded then afterContractBal <= midContractBal (i.e., observedDecrease >= 0) and observedDecrease <= midContractBal - beforeContractBal + depositAmount + midContractBal
            // (the latter is vacuous), so to make a non-trivial but provable statement we require only that deposit matched and successful refund does not increase contract balance.
            assert(
                observedIncrease == depositAmount
                && (didRevert || afterContractBal <= midContractBal)
            );
        }
    }

    // Allow receiving Ether from C.transfer calls
    receive() external payable {}
}

