    // single public function driving the property test
    // We take an amount to deposit first, to establish a positive balances(msg.sender) for this contract.
    function run(uint256 depositAmount) public payable {
        // ensure the test contract has enough ETH to fund the deposit
        require(address(this).balance >= depositAmount);

        // observe balances: use the public getter balances(address) that exists for mapping? Note: balances is not public in C, so it has no getter. We cannot read it directly.
        // The only observable way to know an account's recorded balance is via contract behavior; but refund transfers that amount to msg.sender and sets internal balance to 0.
        // We'll record contract and this-address balances before the refund and after, and also check that after a successful refund the contract's balance changed by the observed transfer amount and this contract received that amount, and that repeated refund afterwards transfers zero.

        // Step 1: deposit some Ether into c from this test contract
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Observe balances before refund attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Attempt refund: catch whether it reverts
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // Observe balances after refund attempt
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // Now, to assert a general property about refund(): If refund succeeded then this contract's balance increased by exactly the amount that C's balance decreased by, and a subsequent refund does not change balances further (since internal balance should be zero). If refund reverted then balances remained unchanged.
        // To test the 'subsequent refund does not change balances' we attempt a second refund and observe no further change when the first succeeded.
        bool secondReverted;
        uint256 midC = afterC;
        uint256 midThis = afterThis;
        try c.refund() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 finalC = address(c).balance;
        uint256 finalThis = address(this).balance;

        // Build the assertion:
        // Case A: refund reverted -> balances unchanged from before
        // Case B: refund succeeded -> (beforeC - afterC) == (afterThis - beforeThis) and second refund either reverts or transfers zero (so finalC == midC and finalThis == midThis)
        assert(
            (refundReverted && afterC == beforeC && afterThis == beforeThis)
            || (
                !refundReverted
                && beforeC >= afterC // no underflow; the contract's balance should not increase as result of refund
                && afterThis >= beforeThis // this contract should not lose Ether from refund
                && (beforeC - afterC) == (afterThis - beforeThis)
                && finalC == midC
                && finalThis == midThis
            )
        );
    }

    receive() external payable {}
}

