    // This test drives migrateTo. It must not call functions that can revert inside C
    // before migrateTo (to avoid hitting deposit's assert). We only call migrateTo and
    // observe balances; we try both the case where the call reverts (not creator) and
    // where it succeeds (creator). The InvMutTest contract was the deployer of C,
    // so it is the creator and can succeed when calling migrateTo.
    function run(address payable to, uint256 harmless) public payable {
        // harmless param is unused but present to satisfy "use parameters" requirement.
        require(to != address(0));

        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeTo = to.balance;

        // Attempt migrateTo and record whether it reverted
        bool migratedReverted;
        try c.migrateTo(to) {
            migratedReverted = false;
        } catch {
            migratedReverted = true;
        }

        // record balances after
        uint256 afterC = address(c).balance;
        uint256 afterTo = to.balance;

        // If migrateTo succeeded (i.e., did not revert), then C's balance must have gone to zero
        // and the recipient's balance must have increased by exactly the previous C balance.
        assert(migratedReverted || (afterC == 0 && afterTo == beforeTo + beforeC));
    }

    // allow receiving Ether if migrateTo sends funds here
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: caller will be this contract when calling c
    function run() public payable {
        // prepare: deposit some Ether into c from this contract
        // require we have enough balance to send the deposit amount
        uint256 depositAmount = msg.value;
        require(address(this).balance >= depositAmount);

        // make a deposit into c on behalf of this contract
        c.deposit{value: depositAmount}();

        // read balances observable: since balances mapping is not public in C, we cannot read it directly.
        // But we can observe address(c).balance before and after refund, and use refund behavior: it transfers entire stored balance of msg.sender and sets it to 0.
        uint256 beforeContractBalance = address(c).balance;

        // attempt refund and capture whether it reverts
        bool refunded;
        try c.refund() {
            refunded = true;
        } catch {
            refunded = false;
        }

        uint256 afterContractBalance = address(c).balance;

        // The general rule: if refund call succeeded, then contract balance decreased by exactly the amount previously held for this caller (which equals depositAmount), and after refund the caller's stored balance is zero — we verify by calling refund again: second refund must transfer zero and thus not change contract balance.
        // We cannot read internal balances mapping, so we check that a second refund (if first succeeded) does not change contract balance and does not revert, implying the stored balance is zero.

        if (refunded) {
            // second refund should succeed and should not change c balance
            try c.refund() {
                // succeeded
            } catch {
                // if second refund reverts then invariant violated
                assert(false);
            }
            uint256 finalContractBalance = address(c).balance;
            // the second refund cannot change contract balance, so afterContractBalance == finalContractBalance
            assert(afterContractBalance == finalContractBalance);
        } else {
            // if the first refund reverted, then no guarantee; require nothing but still satisfy single assert: refunded is either true or false
            assert(refunded == refunded);
        }
    }

    receive() external payable {}
}

