    // single public entry executing the property test
    // params: an deposit amount to fund c from this contract, and a second deposit
    // We will: deposit amount1, deposit amount2, read balance, call refund(), observe whether it reverted,
    // and assert that if refund did not revert then the stored balance became zero and address(this) gained exactly the prior stored amount and address(c).balance decreased by that amount.
    function run(uint256 amount1, uint256 amount2) public payable {
        require(address(this).balance >= amount1 + amount2);

        // make two deposits on behalf of this contract's address (InvMutTest is msg.sender for c calls)
        c.deposit{value: amount1}();
        c.deposit{value: amount2}();

        // read the recorded balance for this contract (auto getter: balances(address))
        uint256 beforeStored = c.balances(address(this));
        uint256 beforeCbal = address(c).balance;
        uint256 beforeSelf = address(this).balance;

        bool reverted;
        // call refund and capture whether it reverted
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterStored = c.balances(address(this));
        uint256 afterCbal = address(c).balance;
        uint256 afterSelf = address(this).balance;

        // General rule: if refund did not revert, then the stored balance for this caller becomes zero,
        // the contract's ether balance decreases by exactly beforeStored, and this contract's ether balance increases by exactly beforeStored.
        assert(reverted || (afterStored == 0 && beforeCbal - afterCbal == beforeStored && afterSelf - beforeSelf == beforeStored));
    }

    // accept plain ether sent to this contract (so refunds can be received)
    receive() external payable {}
}

contract InvMutTest {
