contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some funds, then attempt withdraw(amount). If withdraw doesn't revert
    // it must have been allowed by the contract's require(amount <= balances[msg.sender]).
    // We cannot read balances directly, but we can observe that after a successful withdraw,
    // calling refund() will transfer at most the remaining recorded balance (which when summed
    // with the withdrawn amount equals the recorded balance before withdraw). We assert that
    // if withdraw succeeds then (withdrawn amount) + (amount obtained from refund) == the
    // recorded balance prior to withdraw, observable via external Ether movements.
    // To avoid triggering deposit's assert, we ensure deposits are small enough by requiring
    // non-zero but safe values and that this contract has enough balance.

    // Single public entry executing the property test
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);

        // Make a deposit so that this contract has a recorded balance in c
        c.deposit{value: depositAmount}();

        // Record external balances before withdraw
        uint256 beforeC = address(c).balance;
        uint256 beforeSelf = address(this).balance;

        bool withdrew;
        // try withdraw; record whether it reverted
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // Now call refund to collect any remaining recorded balance (or revert)
        bool refundReverted;
        uint256 afterWithdrawC = address(c).balance;
        uint256 afterWithdrawSelf = address(this).balance;
        uint256 refundReceived = 0;
        try c.refund() {
            refundReverted = false;
            refundReceived = address(this).balance - afterWithdrawSelf;
        } catch {
            refundReverted = true;
            refundReceived = 0;
        }

        uint256 finalC = address(c).balance;

        // If withdraw succeeded then the sum of Ether externally received by this contract
        // from the successful withdraw (difference between afterWithdrawSelf and beforeSelf)
        // plus the Ether received by refund (refundReceived) equals the initial recorded amount
        // that this contract put into c (which equals beforeC - (beforeSelf - address(this).balance at deposit time)).
        // Since we only made one deposit of depositAmount, the initial recorded balance for this contract
        // in c equals depositAmount. So assert: if withdraw succeeded then
        // (amount actually sent by withdraw) + refundReceived == depositAmount.
        // We compute amount actually sent by withdraw as (afterWithdrawSelf - beforeSelf).

        uint256 withdrewAmountActually = 0;
        if (withdrew) {
            // afterWithdrawSelf captured before we called refund; compute from that
            withdrewAmountActually = afterWithdrawSelf - beforeSelf;
        }

        // General rule assertion
        assert(!withdrew || (withdrewAmountActually + refundReceived == depositAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry executing the property test
    // We take depositAmount and withdrawAmount as inputs and ensure we have funds to deposit.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this contract has the Ether to perform the deposit and avoid zero deposits
        require(depositAmount > 0 && address(this).balance >= depositAmount);

        // Make a single deposit so this contract has a recorded balance in c
        c.deposit{value: depositAmount}();

        // Record balances immediately before attempting withdraw
        uint256 beforeSelf = address(this).balance;

        bool withdrawSucceeded;
        // attempt withdraw; record whether it reverted
        try c.withdraw(withdrawAmount) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // Capture balance after withdraw (but before refund)
        uint256 afterWithdrawSelf = address(this).balance;

        // Attempt refund; if it reverts we treat received refund as zero
        uint256 refundReceived = 0;
        try c.refund() {
            refundReceived = address(this).balance - afterWithdrawSelf;
        } catch {
            refundReceived = 0;
        }

        // Ether actually received from withdraw (zero if it reverted)
        uint256 withdrawReceived = withdrawSucceeded ? (afterWithdrawSelf - beforeSelf) : 0;

        // General rule: if withdraw succeeded then withdrawReceived + refundReceived == depositAmount
        assert(!withdrawSucceeded || (withdrawReceived + refundReceived == depositAmount));
    }

    receive() external payable {}
}
